rtl:
always_ff @(posedge clk or negedge rst_n) begin
  if (!rst_n) state <= 2'h0;
  else case (state)
    2'h0: if (req) state <= 2'h1;
    2'h1: if (!req) state <= 2'h0;
    // States 2 and 3 have no branch — synthesized as don't-care
  endcase
end

fix_replacement:
always_ff @(posedge clk or negedge rst_n) begin
  if (!rst_n) state <= 2'h0;
  else case (state)
    2'h0: if (req) state <= 2'h1;
    2'h1: if (!req) state <= 2'h0;
    default: state <= 2'h0;  // Escape illegal states
  endcase
end
